    examples: [
      { en: 'The update will have been deployed by Monday.', ru: 'К понедельнику обновление будет выкачено.' },
      { en: 'All documents will have been signed by tomorrow.', ru: 'К завтрашнему дню все документы будут подписаны.' },
      { en: 'Will the bugs have been fixed by the deadline?', ru: 'Баги будут исправлены к дедлайну?', q: true },
    ],
    compare: ['passive-future-simple', 'future-perfect'],
