  // ──────────────────────────── REPORTED SPEECH ────────────────────────────
  'reported-statements': {
    title: 'Reported Statements',
    formula: 'say / tell + (that) + sentence',
    detail: 'Say и tell различаются адресатом: say просто говорит, tell обязательно кому-то — told me. Нужно ли сдвигать время, решает тема «Real-Life Logic».',
    markers: ['he said', 'she told me', 'explained', 'mentioned'],
    use: [
      { key: true, en: 'say / tell + (that) + sentence', ru: 'Передаём чужие слова своими: say — просто сказал, tell — сказал кому-то.', ex: 'He said (that) he works remotely. — Он сказал, что работает удалённо.' },
      { en: '“that” is usually dropped', ru: 'В живой речи that чаще опускают, чем произносят.', ex: 'She told me she is working on the report. — Она сказала мне, что работает над отчётом.' },
      { key: true, en: 'explain (that) + sentence', ru: 'Объяснил — когда передаём причину.', ex: 'He explained that the issue was on the API side. — Он объяснил, что проблема была на стороне API.' },
      { key: true, en: 'mention (that) + sentence', ru: 'Упомянул вскользь, между делом.', ex: 'She mentioned that QA will test it tomorrow. — Она упомянула, что QA протестируют это завтра.' },
    ],
    examples: [
      { en: 'He said he’s working on the release.', ru: 'Он сказал, что работает над релизом.' },
      { en: 'She told me she’ll be late to the meeting.', ru: 'Она сказала мне, что опоздает на встречу.' },
      { en: 'What did he say about the deadline?', ru: 'Что он сказал про дедлайн?', q: true },
    ],
    compare: ['reported-questions', 'reported-real-life'],
  },
  'reported-questions': {
    title: 'Reported Questions',
    formula: 'ask + if / question word + normal word order',
    detail: 'Знака вопроса в конце косвенного вопроса нет: по форме это обычное утверждение со словом ask.',
    markers: ['asked if', 'asked whether', 'wanted to know'],
    use: [
      { en: 'ask + question word → direct word order', ru: 'После ask порядок слов прямой, как в утверждении, без do/does/did. Это главная ошибка русскоязычных.', ex: '✅ He asked where it was. ❌ He asked where was it.' },
      { key: true, en: 'ask + if / whether → Yes/No question', ru: 'Вопросительного слова нет — его место занимает if или whether.', ex: 'He asked if I could join the meeting.' },
    ],
    examples: [
      { en: 'He asked if I could join the meeting.', ru: 'Он спросил, смогу ли я быть на встрече.' },
      { en: 'She asked where the config file is.', ru: 'Она спросила, где лежит конфиг.' },
      { en: 'Did he ask when the release is?', ru: 'Он спрашивал, когда релиз?', q: true },
    ],
    compare: ['reported-statements'],
  },
  'reported-commands': {
    title: 'Commands & Requests',
    formula: 'tell / ask + person + (not) to + verb',
    detail: 'Одна конструкция на приказ и на просьбу — меняется только глагол перед человеком.',
    markers: ['told me to', 'asked me to', 'not to'],
    use: [
      { key: true, en: 'tell + person + to + verb', ru: 'Указание: руководитель — команде.', ex: 'He told me to restart the container.' },
      { key: true, en: 'ask + person + to + verb', ru: 'Просьба между равными, вежливый вариант.', ex: 'She asked me to send the report.' },
      { key: true, en: 'tell / ask + person + not to + verb', ru: 'Отрицание: not ставится перед to, а не после.', ex: 'They told me not to update the branch.' },
    ],
    examples: [
      { en: 'He told me to restart the container.', ru: 'Он сказал мне перезапустить контейнер.' },
      { en: 'They told me not to update the branch.', ru: 'Они сказали мне не обновлять ветку.' },
      { en: 'What did she ask you to do?', ru: 'Что она попросила тебя сделать?', q: true },
    ],
    compare: ['reported-statements'],
  },
  'reported-real-life': {
    title: 'Real-Life Logic (tense by meaning)',
    formula: 'сдвигать время или нет — по актуальности факта',
    detail: 'Механический сдвиг времён из учебника в живой речи работает не всегда. Смотри на факт: он ещё верен — оставляй настоящее; уже неактуален — сдвигай в прошедшее.',
    markers: ['he said he works', 'still', 'now'],
    use: [
      { en: 'Still true → keep the present', ru: 'Факт в силе — время не сдвигаем.', ex: 'She said she works remotely.' },
      { en: 'No longer true → shift to the past', ru: 'Тогда было так, сейчас иначе — сдвигаем в прошедшее.', ex: 'She said she worked remotely.' },
      { en: 'Still in progress → keep the continuous', ru: 'Процесс не закончен — оставляем настоящее.', ex: 'He said he is fixing the bug.' },
      { en: 'General truth → never shifts', ru: 'Общие истины не сдвигают во времени никогда.', ex: 'He said the sun rises in the east.' },
    ],
    examples: [
      { en: 'She said she works remotely.', ru: 'Она всё ещё работает удалённо.' },
      { en: 'She said she worked remotely.', ru: 'Тогда работала, сейчас — нет.' },
      { en: 'Did he say he is still fixing the bug?', ru: 'Он сказал, что всё ещё чинит баг?', q: true },
    ],
    compare: ['reported-statements'],
  },

